// CORREÇÃO (auditoria v2.1): o mock anterior usava um node Set com chaves
// como "copywriting.telegram_post" esperando que o n8n as transformasse
// em objeto aninhado (comportamento de "dot notation", que depende de uma
// opção nem sempre ativada). Um node Code com o objeto já aninhado
// explicitamente elimina essa ambiguidade e garante que o teste manual
// reflita fielmente o payload real enviado pelo worker.
return [{
  json: {
    product_id: 'job_teste_123',
    title: 'Escova de Limpeza Elétrica Multifuncional',
    price: { promotional: 69.90, original: 79.90, currency: 'BRL' },
    copywriting: { telegram_post: 'Você ainda perde horas esfregando o azulejo do banheiro?' },
    media: { rendered_video_path: '' },
    approval: { status: 'PENDING', approved_at: null }
  }
}];

// CORREÇÃO (auditoria v2.1): validação do header x-webhook-secret — ver
// worker/worker.py::_notificar_aprovacao, que é quem chama este webhook.
const vindoDeWebhook = $json.headers !== undefined;
const secretEsperado = $env.WEBHOOK_SHARED_SECRET;
if (vindoDeWebhook && secretEsperado) {
  const secretRecebido = $json.headers['x-webhook-secret'];
  if (secretRecebido !== secretEsperado) {
    throw new Error('Webhook não autorizado: header x-webhook-secret ausente ou incorreto.');
  }
}

const body = $json.body || $json || {};
const titulo = body?.title || 'Produto sem título';
const hook = body?.copywriting?.telegram_post || '(sem hook gerado)';
const preco = body?.price?.promotional ?? body?.price?.original ?? 0;
const jobId = body?.product_id || 'sem_id';
const videoPath = body?.media?.rendered_video_path || '';
// CORREÇÃO: distingue erro real de pipeline (definido pelo worker em
// approval.status === 'ERROR') de "apenas sem vídeo", que não é uma falha
// e não deveria bloquear a aprovação do conteúdo.
const erroPipeline = body?.approval?.status === 'ERROR';
const motivoErro = body?.erro || 'motivo não informado';

const caption = `🛒 *Novo conteúdo pronto para revisão*\n\n` +
  `Produto: ${titulo}\n` +
  `Preço: R$ ${Number(preco).toFixed(2)}\n` +
  `Hook: "${hook}"\n\n` +
  `Aprovar publicação?`;

const replyMarkup = JSON.stringify({
  inline_keyboard: [[
    { text: '✅ Aprovar', callback_data: 'approve:' + jobId },
    { text: '❌ Rejeitar', callback_data: 'reject:' + jobId }
  ]]
});

return [{
  json: { ...body, job_id: jobId, caption, videoPath, erroPipeline, motivoErro, replyMarkup }
}];
